    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return clamp_step(b - a)

    def dist2(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    def as_point(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    env = observation.get("environment_name", "resource_collection")
    self_pos = as_point(observation.get("self_position")) or (0, 0)
    opp_pos = as_point(observation.get("opponent_position")) or (self_pos[0], self_pos[1])

    sx, sy = self_pos
    ox, oy = opp_pos

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [step_toward(sx, ox), step_toward(sy, oy)]
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
