        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "frontier_cells", "targets"):
            vals = observation.get(key) or []
            if vals:
                candidates = vals
                break
        if candidates:
            best = min(candidates, key=lambda p: dist2(p[0], p[1], sx, sy))
            return [step_toward(sx, best[0]), step_toward(sy, best[1])]
        return [step_toward(sx, ox), step_toward(sy, oy)]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        carrying = observation.get("carrying", 0)
        if carrying and (gw and gh):
            cx = (gw - 1) // 2
            cy = (gh - 1) // 2
            return [step_toward(sx, cx), step_toward(sy, cy)]
        best = min(resources, key=lambda p: dist2(p[0], p[1], sx, sy))
        return [step_toward(sx, best[0]), step_toward(sy, best[1])]

    danger = observation.get("danger_positions") or observation.get("enemy_positions") or []
    if danger:
        nearest = min(danger, key=lambda p: dist2(p[0], p[1], sx, sy))
        return [step_toward(nearest[0], sx), step_toward(nearest[1], sy)]

    return [step_toward(sx, ox), step_toward(sy, oy)]

